#!/usr/bin/env bash
# Apollo -> HubSpot junk record cleanup: batch archive script
# Generated by Claude on 2026-07-10. Reversible: archived records sit in
# HubSpot's recycle bin for 90 days (Settings -> Objects -> Contacts/Companies -> Recycle Bin).
#
# USAGE:
#   Run this from a machine with real internet access (your own terminal, not a sandbox).
#   It reads HUBSPOT_ACCESS_TOKEN from toolbx-sales-hub/.env.local automatically.
#
#   cd /path/to/toolbx-sales-hub
#   bash apollo-cleanup-archive.sh
#
set -uo pipefail

ENV_FILE="$(dirname "$0")/.env.local"
if [ ! -f "$ENV_FILE" ]; then
  echo "ERROR: .env.local not found next to this script. Aborting." >&2
  exit 1
fi

HUBSPOT_TOKEN=$(grep '^HUBSPOT_ACCESS_TOKEN' "$ENV_FILE" | cut -d= -f2- | tr -d '"' | tr -d "'" | xargs)
if [ -z "$HUBSPOT_TOKEN" ]; then
  echo "ERROR: HUBSPOT_ACCESS_TOKEN not found or empty in .env.local. Aborting." >&2
  exit 1
fi

archive_batch() {
  local object_type="$1"
  shift
  local ids=("$@")
  local payload="{\"inputs\":["
  local first=1
  for id in "${ids[@]}"; do
    if [ $first -eq 1 ]; then first=0; else payload+=","; fi
    payload+="{\"id\":\"$id\"}"
  done
  payload+="]}"

  local attempt=1
  local max_attempts=3
  while [ $attempt -le $max_attempts ]; do
    http_code=$(curl -s -o /tmp/hs_archive_resp.json -w "%{http_code}" \
      -X POST "https://api.hubapi.com/crm/v3/objects/${object_type}/batch/archive" \
      -H "Authorization: Bearer $HUBSPOT_TOKEN" \
      -H "Content-Type: application/json" \
      -d "$payload")

    if [ "$http_code" = "204" ] || [ "$http_code" = "200" ]; then
      echo "OK"
      return 0
    elif [ "$http_code" = "429" ]; then
      echo "Rate limited (attempt $attempt/$max_attempts), waiting 10s..." >&2
      sleep 10
      attempt=$((attempt+1))
    else
      echo "FAILED (HTTP $http_code): $(cat /tmp/hs_archive_resp.json)" >&2
      return 1
    fi
  done
  echo "FAILED after $max_attempts attempts (rate limited)" >&2
  return 1
}

run_archive() {
  local object_type="$1"
  local label="$2"
  shift 2
  local all_ids=("$@")
  local total=${#all_ids[@]}
  local batch_size=100
  local success=0
  local failed=0
  local batch_num=0
  local num_batches=$(( (total + batch_size - 1) / batch_size ))

  echo "=== Archiving $total $label in $num_batches batches of up to $batch_size ==="

  for ((i=0; i<total; i+=batch_size)); do
    batch_num=$((batch_num+1))
    batch=("${all_ids[@]:i:batch_size}")
    first_id="${batch[0]}"
    last_id="${batch[$((${#batch[@]}-1))]}"
    echo "Archiving $label batch $batch_num/$num_batches (IDs: $first_id..$last_id, count: ${#batch[@]})"

    if archive_batch "$object_type" "${batch[@]}" > /tmp/hs_batch_result.txt 2>/tmp/hs_batch_err.txt; then
      success=$((success + ${#batch[@]}))
    else
      failed=$((failed + ${#batch[@]}))
      echo "  -> Batch $batch_num FAILED: $(cat /tmp/hs_batch_err.txt)"
      fail_pct=$(( failed * 100 / (success + failed) ))
      if [ $fail_pct -gt 20 ] && [ $((success + failed)) -gt 100 ]; then
        echo "ERROR: more than 20% of $label batches have failed. Stopping. Review before re-running." >&2
        echo "$label: $success succeeded, $failed failed (of $((success+failed)) attempted so far)"
        return 1
      fi
    fi
    sleep 0.5
  done

  echo "$label archived: $success succeeded, $failed failed (of $total attempted)"
}

echo "Starting TOOLBX Apollo cleanup archive..."
echo ""

